usage:
# Read cached usage
GET /api/usage

# Force a manual check
POST /api/refresh

# Use the MCP endpoint from OpenCode
{
  "mcp": {
    "servers": {
      "ai-usage": {
        "type": "remote",
        "url": "https://usage.example.com/mcp",
        "headers": { "Authorization": "Basic {env:AI_USAGE_BASIC}" }
      }
    }
  }
}
